import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    defaults: dict[str, str] = {}
    current_section: str | None = None
    last_key: str | None = None
    raw_lines = text.splitlines()

    i = 0
    while i < len(raw_lines):
        line = raw_lines[i]
        stripped = line.lstrip()

        # Rule 3: ignore empty or comment lines
        if not stripped or stripped[0] in (';', '#'):
            i += 1
            continue

        # Rule 6: continuation line check
        if line[0].isspace():
            if last_key is None:
                raise ValueError("Continuation line without preceding key line")
            if current_section is None:
                raise ValueError("Continuation line outside section")
            sections[current_section][last_key] += '\n' + stripped
            i += 1
            continue

        # Rule 1: Section header
        if stripped.startswith('[') and stripped.endswith(']'):
            sec_name = stripped[1:-1]
            current_section = sec_name
            if sec_name == 'DEFAULT':
                defaults.update(sections.get(sec_name, {}))
            else:
                sections[sec_name] = {}
            last_key = None
            i += 1
            continue

        # Rule 10: Key line before any section header
        if current_section is None:
            raise ValueError("Key line before any section header")

        # Rule 2: Parse key=value or key:value
        eq_pos = line.find('=')
        colon_pos = line.find(':')
        candidates = [p for p in (eq_pos, colon_pos) if p != -1]
        if not candidates:
            raise ValueError(f"Malformed line: {line}")

        split_idx = min(candidates)
        raw_key = line[:split_idx]
        raw_val = line[split_idx+1:]

        key = raw_key.strip().lower()
        if not key:
            raise ValueError(f"Empty key in line: {line}")

        # Process value
        val = raw_val.strip()
        if val.startswith('"'):
            end_quote = val.find('"', 1)
            if end_quote == -1:
                raise ValueError("Unclosed quote in value")
            content = val[1:end_quote]
            # Check for inline comment after closing quote
            rest = val[end_quote+1:]
            cmt_idx = -1
            for pat in (' ;', ' #'):
                i_cmt = rest.find(pat)
                if i_cmt != -1 and (cmt_idx == -1 or i_cmt < cmt_idx):
                    cmt_idx = i_cmt
            # If comment found, ignore text before it (typically whitespace)
            final_val = content
        else:
            cmt_idx = -1
            for pat in (' ;', ' #'):
                i_cmt = val.find(pat)
                if i_cmt != -1 and (cmt_idx == -1 or i_cmt < cmt_idx):
                    cmt_idx = i_cmt
            if cmt_idx != -1:
                val = val[:cmt_idx]
            final_val = val.rstrip()  # Rule 2: values stripped

        # Rule 7: later value wins
        sections[current_section][key] = final_val
        last_key = key
        i += 1

    # Rule 8: Merge defaults
    for sec in sections:
        for k, v in defaults.items():
            if k not in sections[sec]:
                sections[sec][k] = v

    # Rule 9: Interpolation
    ref_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve(sec: str, key: str, cache: dict, resolving: set) -> str:
        cache_key = (sec, key)
        if cache_key in cache:
            return cache[cache_key]
        if cache_key in resolving:
            raise ValueError("Interpolation cycle detected")
        resolving.add(cache_key)

        current_val = sections[sec][key]

        def replacer(match):
            ref = match.group(1)
            if ':' in ref:
                s_ref, k_ref = ref.split(':', 1)
                if s_ref not in sections:
                    raise KeyError(f"Section '{s_ref}' not found")
                if k_ref not in sections[s_ref]:
                    raise KeyError(f"Key '{k_ref}' not found in section '{s_ref}'")
                target_sec, target_key = s_ref, k_ref
            else:
                if ref not in sections[sec]:
                    raise KeyError(f"Key '{ref}' not found in section '{sec}'")
                target_sec, target_key = sec, ref
            return resolve(target_sec, target_key, cache, resolving)

        resolved_val = ref_pattern.sub(replacer, current_val)
        resolving.discard(cache_key)
        cache[cache_key] = resolved_val
        return resolved_val

    resolved_cache = {}
    for sec_name in list(sections.keys()):
        for key in list(sections[sec_name].keys()):
            sections[sec_name][key] = resolve(sec_name, key, resolved_cache, set())

    return sections
