def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    name_map: dict[str, str] = {}
    totals: dict[str, float] = {}

    for row in rows:
        cust_raw = row.get("customer")
        if not isinstance(cust_raw, str):
            continue
        trimmed = cust_raw.strip()
        if not trimmed:
            continue

        lower = trimmed.lower()
        if lower not in name_map:
            name_map[lower] = trimmed

        amt_raw = row.get("amount")
        if not isinstance(amt_raw, str):
            continue
        try:
            cleaned = amt_raw.strip().replace('$', '').replace(',', '')
            if not cleaned:
                continue
            amount = float(cleaned)
        except ValueError:
            continue

        totals[lower] = totals.get(lower, 0.0) + amount

    results = [(name_map[lower], round(total, 2)) for lower, total in totals.items()]
    results.sort(key=lambda x: (-x[1], x[0]))
    return results[:n]
